396	                // add original name in table comment
397	                String commentExtra = "Original model name - " + modelName + ".";
398	                modelDescription = (modelDescription == null || modelDescription.isEmpty()) ? commentExtra
399	                        : modelDescription + ". " + commentExtra;
400	            }
401	
402	            if (modelVendorExtensions.containsKey(VENDOR_EXTENSION_POSTGRESQL_SCHEMA)) {
403	                // user already specified schema values
404	                LOGGER.info("Found vendor extension in '{}' model, autogeneration skipped", modelName);
405	            } else {
406	                modelVendorExtensions.put(VENDOR_EXTENSION_POSTGRESQL_SCHEMA, postgresqlSchema);
407	                postgresqlSchema.put("tableDefinition", tableDefinition);
408	                tableDefinition.put("tblName", tableName);
